class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict
        
        # Dictionary to store the count of each special substring
        special_count = defaultdict(int)
        
        n = len(s)
        
        # Generate all special substrings and count their occurrences
        for i in range(n):
            for j in range(i, n):
                substring = s[i:j+1]
                # Check if the substring is special
                if len(set(substring)) == 1:
                    special_count[substring] += 1
                else:
                    break  # No need to extend further if not special
        
        # Find the longest special substring that occurs at least thrice
        max_length = -1
        for substring, count in special_count.items():
            if count >= 3:
                max_length = max(max_length, len(substring))
        
        return max_length
